"""Pending original metadata display mechanisms read in vsprintf.c 1687–2233."""
def register(topic,q,detail):
    def lesson(title,symbol,why,principle,use,reading,qa,cards):
        topic(title,'관찰·디버깅','lib/vsprintf.c',symbol,why,principle,use,reading,
              *(q(*x) for x in qa),details=[detail(*x) for x in cards])
    lesson('UUID 출력·Index Table과 Case 선택','uuid_string',
      '16byte 식별자의 표시에서 자료 순서와 hex 대소문자를 각각 선택하는 방식을 배웁니다.',
      '기본은 uuid_index와 소문자입니다. Suffix l은 guid_index로, L은 대문자 선택 뒤 guid_index로, B는 기본 index의 대문자로 바꿉니다. Index table 순서로 byte를 hex 두 문자씩 저장하고 3·5·7·9번째 byte 뒤에 hyphen을 넣습니다. 내부 NUL 뒤 string_nocheck로 외부 buffer에 출력합니다.',
      'UUID와 GUID의 byte 배열 계약을 구분하고 16byte 자료의 수명을 보장합니다. 대문자 선택과 endian/index 선택을 같은 기능으로 해석하지 않습니다. 이 함수는 random UUID 생성이나 version bit 검증을 수행하지 않습니다.',
      'index 초기값, L의 fallthrough, 네 hyphen 위치를 읽으세요.',
      [('L suffix가 함께 선택하는 두 기능은?', 'GUID 순서와 대문자 hex이다','UUID 생성과 checksum 검증이다','L은 uc=true 뒤 l branch로 이어져 guid_index를 선택합니다.'),
       ('B suffix이면 GUID byte 순서로 바뀌는가?', '기본 UUID 순서를 유지한다','L과 언제나 같은 순서이다','B는 uc만 바꿉니다. Index table 선택은 l·L에서 수행합니다.')],
      [('고정 형태','16byte는 hex 32문자와 hyphen 4개, NUL 1개가 필요합니다. 실제 외부 출력은 width·precision·buffer 공간의 영향을 별도로 받습니다.'),
       ('자료와 표시','이미 만들어진 ID의 표시 함수입니다. 이전 UUID 생성·index 수업과 연결하되 표시할 수 있다는 사실을 유효 version의 검증이라고 해석하지 않습니다.')])
    lesson('Netdev Feature 표시·타입 크기와 Hex 폭','netdev_bits',
      'Network feature bit 집합을 이름 대신 고정 폭 hex로 표시할 때 실제 자료 타입을 따라가는 원리를 배웁니다.',
      'Pointer를 확인한 뒤 F selector에서 netdev_features_t 값을 읽고 sizeof(netdev_features_t)를 얻습니다. special_hex_number에 값과 크기를 전달해 0x와 타입 크기의 두 배인 hex 자리를 표시합니다. 다른 selector이면 (%pN?) 오류 문자열을 출력합니다.',
      '유효 netdev_features_t 객체의 주소를 전달합니다. Pointer 자체의 주소 값과 pointer가 가리키는 feature 값을 구분합니다. Bit 이름 해독이나 feature 활성화 API로 사용하지 않습니다.',
      '역참조, sizeof 자료 타입, selector 오류, special hex 전달을 읽으세요.',
      [('출력하는 값은 pointer 주소인가?', 'pointer가 가리키는 feature 값이다','항상 pointer 주소 자체이다','명시적 netdev_features_t 역참조 결과를 num에 저장해 출력합니다.'),
       ('Feature 이름별 해독을 이 함수가 하는가?', '수치를 고정 hex로 표시한다','모든 bit를 문자열 이름으로 변환한다','이 body에는 feature 이름 table 탐색이 없습니다. 값·타입 크기를 숫자 helper로 전달합니다.')],
      [('타입 폭','size는 sizeof(ptr)가 아니라 sizeof(netdev_features_t)입니다. 자료 타입을 바꾸는 빌드에서 표시 폭도 그 타입 계약을 따라갑니다.'),
       ('특별 오류','selector가 잘못되어도 임의 타입으로 읽지 않고 질문형 오류 문자열을 선택합니다. 주소 사전 검사와 타입 선택 오류는 서로 다른 검사입니다.')])
    lesson('FourCC 표시·Unaligned 읽기와 Endian 표식','fourcc_string',
      '영상 format 등의 네 문자 코드를 읽을 때 정렬되지 않은 접근과 별도의 endian 표식 bit를 이해합니다.',
      'cc suffix를 확인하고 pointer 검사 뒤 get_unaligned로 u32 값을 읽습니다. BIT(31)을 지운 val에서 낮은 byte부터 네 문자를 만들되 ASCII printable만 그대로, 다른 문자는 dot으로 표시합니다. 원래 orig의 BIT(31)에 따라 big-endian 또는 little-endian 설명을 붙이고 orig 전체를 hex로 이어 표시합니다.',
      '유효 u32 자료를 제공하고 정렬이 보장되지 않는 읽기에는 get_unaligned의 계약을 사용합니다. BIT(31)은 코드의 표시 속성이며 현재 CPU endian을 자동 탐지한 결과와 다릅니다. 원래 hex 값에는 표식 bit도 남습니다.',
      'suffix→검사→get_unaligned→표식 제거→printable→orig hex를 읽으세요.',
      [('BIT(31)을 지우는 대상은?', '네 문자 해석용 val이다','원본 orig를 영구 변경한다','orig는 보존하고 val=orig & ~BIT(31)로 만듭니다. 뒤의 hex 출력에는 orig를 사용합니다.'),
       ('제어 문자인 byte를 네 문자 영역에 그대로 출력하는가?', 'dot으로 바꾼다','모든 byte를 raw 제어 문자로 보낸다','isascii와 isprint 조건으로 사람이 읽을 수 있는 문자만 유지합니다.')],
      [('표식과 CPU','표시의 big/little 문구는 orig의 bit를 해석한 것입니다. Host CPU의 endian을 판정하거나 byte 배열을 무조건 swap하는 코드가 아닙니다.'),
       ('순서','i*8만큼 오른쪽 shift해 낮은 byte부터 읽습니다. 같은 숫자 값의 네 문자 의미와 메모리에 저장된 byte 순서는 host endian 계약과 함께 이해합니다.')])
    lesson('물리·DMA 주소 표시·값을 담은 Pointer','address_val',
      '커널의 가상 pointer와 그 안에 저장된 물리·DMA 주소가 서로 다른 표현임을 배웁니다.',
      'Pointer 사전 검사 뒤 d selector는 dma_addr_t, p와 그 외는 phys_addr_t로 역참조합니다. 선택 타입의 sizeof와 값을 special_hex_number에 전달합니다. 읽기용 pointer 자체를 출력하지 않고 저장된 address value를 출력합니다.',
      'Format이 요구하는 타입의 실제 객체를 전달합니다. CPU 물리 주소와 device가 사용하는 DMA 주소를 언제나 같은 값으로 가정하지 않습니다. 출력된 값을 가상 pointer로 바로 역참조하지 않습니다.',
      'd와 p/default의 타입 cast, sizeof, 값 전달을 읽으세요.',
      [('d selector의 pointer는 무엇을 가리켜야 하는가?', 'dma_addr_t 값 객체이다','항상 char 문자열이다','이 branch는 dma_addr_t로 역참조합니다. 유효 자료와 타입을 caller가 맞춰야 합니다.'),
       ('이 helper가 DMA mapping을 새로 만드는가?', '기존 주소 값을 표시한다','출력하면서 자동으로 mapping을 할당한다','Body는 자료 읽기와 숫자 표시입니다. Mapping API 호출은 없습니다.')],
      [('주소 공간 구분','가상 주소, 물리 주소, DMA 주소의 관계는 architecture와 IOMMU·device mapping 정책에 따라 달라집니다. 같은 hex 표기라고 같은 주소 공간은 아닙니다.'),
       ('Fallback selector','알 수 없는 fmt[1]도 이 body에서는 phys_addr_t 경로입니다. 다른 formatter의 질문형 오류 계약과 동일하다고 가정하지 않습니다.')])
    lesson('RTC 날짜 출력·Raw 필드와 Calendar 보정','rtc_str',
      '날짜 구조체의 year·month 저장 기준을 사람이 읽는 날짜로 바꾸는 규칙을 배웁니다.',
      'rtc_str은 기본 date와 time을 모두 표시합니다. 초기 d는 time을, t는 date를 끕니다. 뒤의 r은 raw, s는 date/time separator를 space로 바꿉니다. date_str은 raw가 아니면 tm_year+1900,tm_mon+1을 사용하고 4·2자리 최소 폭으로 표시합니다. time_str은 hour·minute·second를 두 자리와 colon으로 연결합니다. 기본 separator는 T입니다.',
      '유효 rtc_time과 필드 저장 기준을 확인합니다. Raw와 일반 calendar 표시를 구분합니다. Width는 최소 폭이며 날짜 범위 유효성을 이 함수가 자동 검사하거나 잘못된 필드를 정규화한다고 가정하지 않습니다.',
      '첫 d/t, r/s 수집, year/month offset, T 또는 space를 읽으세요.',
      [('tm_year=124,tm_mon=0의 일반 date 시작은?', '2024-01이다','0124-00이다','일반 모드는 year에 1900, month에 1을 더합니다. Raw 모드는 저장 필드를 그대로 표시합니다.'),
       ('s만 선택하고 date/time 둘 다 표시하면 사이 문자는?', 'space이다','언제나 T이다','s는 iso8601_separator를 false로 바꿉니다. Date/time의 표시 여부는 다른 선택입니다.')],
      [('최소 폭','default_dec04_spec과 dec02_spec은 앞 0을 채우는 최소 폭입니다. 값이 폭보다 길면 전체 숫자가 출력되며 날짜 범위 검사로 대체되지 않습니다.'),
       ('time의 Raw','time_str에 r 인자가 있어도 body는 hour·minute·second를 그대로 사용합니다. Raw의 실제 차이는 date_str의 year/month 보정에서 나타납니다.')])
    lesson('Time64 표시·Calendar 변환과 Format 분배','time64_str',
      '초 단위 시간 값과 분해된 calendar 필드가 서로 다른 자료 형식이며 변환을 거쳐 연결됨을 배웁니다.',
      'time64_str은 time64_to_tm(time,0,&tm)으로 offset 0의 calendar 필드를 얻습니다. 초·분·시·일·월·년·요일·연일을 rtc_time에 복사하고 isdst=0을 설정한 뒤 rtc_str로 표시합니다. time_and_date의 R은 rtc_time pointer, T는 time64_t pointer를 역참조하여 이 함수를 호출하며 다른 selector는 오류 문자열입니다.',
      'R/T format과 실제 자료 타입을 맞춥니다. 유효 pointer 수명과 접근 가능성을 상위 호출 계약에서 보장합니다. Offset 0 변환이 사용자의 임의 local timezone을 자동 선택하는 기능이라고 해석하지 않습니다.',
      'time64_to_tm의 0 offset, 필드 복사, R/T 역참조를 읽으세요.',
      [('time64_to_tm에 전달하는 timezone offset은?', '0이다','현재 사용자 local timezone을 자동 조회한다','원본은 두 번째 인자로 literal 0을 전달합니다. 사용자의 timezone 설정 조회 코드는 없습니다.'),
       ('T selector에 rtc_time 주소를 전달해도 자동 검출하는가?', 'time64_t 객체 주소를 제공해야 한다','함수가 모든 타입을 자동 인식한다','T branch는 time64_t로 바로 역참조합니다. Format과 자료 타입 계약이 필요합니다.')],
      [('표시 Adapter','Calendar 산술의 실제 알고리즘은 time64_to_tm 구현에 있습니다. 이 helper는 변환 결과를 RTC 표시 기능으로 연결하는 부분입니다.'),
       ('사전 접근 전제','R은 rtc_str에서 검사하지만 T branch는 값을 읽은 뒤 helper에 전달합니다. 개별 body를 임의 pointer 안전 검증 API로 사용하지 않습니다.')])
    lesson('Clock 표시·지원 CONFIG와 Name Fallback','clock',
      '장치의 clock 객체 표시가 빌드 설정에 따라 이름·ID·오류 표현으로 달라지는 이유를 배웁니다.',
      'CONFIG_HAVE_CLK가 꺼져 있으면 (%pC?)를 표시합니다. 지원되면 pointer 검사 뒤 COMMON_CLK 설정에서 __clk_get_name 결과를 string으로 출력합니다. COMMON_CLK가 아니면 ptr_to_id로 객체 표시 ID를 만듭니다. n selector와 default는 같은 선택 경로입니다.',
      '유효 clk 객체와 선택 clock framework 설정을 확인합니다. 출력된 이름을 실제 clock rate로 해석하지 않습니다. Pointer ID fallback에서는 앞의 key 준비·hash 정책 계약을 따릅니다.',
      'HAVE_CLK의 조기 오류, COMMON_CLK의 compile branch와 ptr_to_id를 읽으세요.',
      [('Clock framework 이름 정보가 없는 대체 분기는?', 'ptr_to_id로 표시한다','항상 clock 주파수 값을 반환한다','COMMON_CLK가 아닌 branch는 객체 pointer의 표시 ID를 사용합니다. Rate 조회는 없습니다.'),
       ('CONFIG_HAVE_CLK가 꺼져 있으면?', '질문형 오류 표시를 선택한다','모든 clk를 강제로 역참조한다','지원 여부를 먼저 검사해 오류 문자열을 반환합니다.')],
      [('표시와 제어','이 helper는 clock enable·disable·rate 설정을 수행하지 않습니다. 표시 결과를 변경 요청의 성공 증거로 사용하지 않습니다.'),
       ('런타임과 빌드','IS_ENABLED 조건과 #ifdef 조건은 코드의 선택 환경을 반영합니다. 한 CONFIG에서 실행한 결과가 모든 빌드 경로의 실행 검증은 아닙니다.')])
    lesson('Flag 이름 Table·Composite Mask와 남은 Bit','format_flags',
      '여러 flag를 이름으로 표시할 때 table 순서와 복합 mask가 결과에 영향을 주는 원리를 배웁니다.',
      'Flags가 남고 table 이름이 있는 동안 각 mask를 확인합니다. (flags&mask)==mask인 항목만 이름을 출력하고 flags&=~mask로 그 bit들을 지웁니다. 남은 값이 있으면 separator를 붙이며 table 끝까지 알려지지 않은 bit가 남으면 hex로 출력합니다. Flags가 처음부터 0이면 loop와 numeric fallback 모두 실행하지 않습니다.',
      '해당 flag domain에 맞는 유효 table을 제공합니다. Composite mask와 개별 mask가 겹치면 앞 항목이 bit를 소비하므로 table 순서의 의미를 확인합니다. 알 수 없는 bit를 없던 것으로 지우지 않습니다.',
      '전체 mask 일치, 소비, separator, 남은 hex fallback을 읽으세요.',
      [('Mask의 일부 bit만 있으면 이름을 출력하는가?', '모든 mask bit가 있어야 한다','하나라도 있으면 무조건 이름을 출력한다','원본 비교는 ==mask입니다. Composite 항목은 필요한 bit가 모두 있을 때 선택합니다.'),
       ('Table에 없는 bit가 남으면?', '남은 수치를 hex로 표시한다','자동으로 모두 삭제한다','마지막 if(flags)가 number를 호출합니다. 알려지지 않은 정보도 표시로 남깁니다.')],
      [('순서와 중복','먼저 선택한 항목은 자신의 mask를 제거합니다. 뒤의 더 작은 mask 이름이 나오지 않을 수 있으므로 table 순서가 표시 정책의 일부입니다.'),
       ('Zero의 표시','이 함수만으로 flags=0은 빈 출력입니다. 상위 page formatter는 전체 hex 값과 괄호를 먼저 표시하므로 서로 다른 함수의 zero 결과를 구분합니다.')])
    lesson('Page Flag 표시·Bit Field Table과 CONFIG 폭','format_page_flags',
      '한 word에 상태 bit와 작은 수치 필드가 함께 들어갈 때 각 영역을 해독하는 자료구조를 배웁니다.',
      '먼저 flags 전체를 hex로 출력하고 괄호를 엽니다. PAGEFLAGS_MASK로 얻은 main 영역은 pageflag_names로 표시합니다. pff table의 section·node·zone·lastcpupid·kasantag는 width가 0이면 건너뛰고, 그 외 (flags>>shift)&mask를 필드 spec으로 출력합니다. Append flag는 separator를 필요한 항목 사이에만 넣으며 마지막 괄호를 닫습니다.',
      '선택 CONFIG가 정한 width·shift·mask를 함께 확인합니다. Width 0인 미정의 필드와 정의되어 있지만 값이 0인 필드를 구분합니다. 출력만으로 page 객체를 참조로 고정하거나 상태 변경을 동기화하지 않습니다.',
      '전체 값, main mask, pff의 width 0, shift/mask, append를 읽으세요.',
      [('정의된 필드의 수치가 0이면 출력에서 생략하는가?', 'width가 0이 아니면 값 0도 표시한다','모든 0 값은 무조건 생략한다','Skip 조건은 값이 아니라 field width입니다. 정의된 필드의 수치 0을 number로 표시합니다.'),
       ('필드가 CONFIG에서 미정의이면 어떤 조건으로 건너뛰는가?', 'pff[i].width==0이다','flags 전체 값이 0일 때만이다','Table의 width가 빌드별 필드 존재를 표현합니다. 전체 flags가 0이어도 정의된 필드 표시는 가능합니다.')],
      [('자료구조','page_flags_fields는 width·shift·mask·숫자 spec pointer·이름을 묶습니다. Table loop가 반복적인 필드 출력 코드를 공통화합니다.'),
       ('정보 보존','처음의 전체 hex 값에는 main bit와 모든 field bit가 함께 있습니다. 이름 해독 결과와 원래 수치를 같이 표시하므로 선택 table 밖의 정보도 확인할 수 있습니다.')])
    lesson('GFP·VMA Flag 분배·포인터 타입 선택','flags_string',
      '같은 형식의 bit 출력이라도 입력 타입과 해독 table이 다르므로 domain 선택이 필요함을 배웁니다.',
      'Pointer 검사 뒤 p는 unsigned long page flags를 format_page_flags로, v는 unsigned long VMA flags와 vmaflag_names로, g는 gfp_t 값과 gfpflag_names로 연결합니다. 모르는 selector는 (%pG?)를 표시합니다. GFP 값은 force cast로 unsigned long 표시 표현에 옮깁니다.',
      '입력 객체와 p/v/g selector를 맞춥니다. Page 상태, VMA 접근 정책, allocator 요청 flag의 bit 의미를 서로 바꿔 해독하지 않습니다. 해독은 관찰 기능이며 할당이나 permission 변경을 수행하지 않습니다.',
      '세 타입 읽기, 세 출력 경로, default 오류를 읽으세요.',
      [('g selector가 읽는 자료 타입은?', 'gfp_t이다','항상 unsigned long 객체이다','GFP 요청 flag의 실제 타입으로 읽고 표시용 unsigned long으로 변환합니다.'),
       ('같은 bit 값이면 모든 domain에서 같은 이름인가?', '해당 domain의 table로 읽어야 한다','숫자만 같으면 언제나 같은 의미다','VMA·GFP·page는 서로 다른 flag 집합입니다. Selector가 올바른 해독 table을 정합니다.')],
      [('강제 Type 표식','__force는 커널의 sparse 타입 검사와 연결되는 cast 표식입니다. 실제 값을 안전하게 검증하거나 객체 크기를 늘리는 runtime 연산이 아닙니다.'),
       ('Page 특별 표시','Page는 main flag 이름뿐 아니라 pff의 수치 필드를 가진 별도 표현입니다. VMA/GFP의 단순 이름 table 출력과 결과 형태가 다릅니다.')])
    lesson('Firmware Node 이름·Parent 참조와 전체 경로','fwnode_full_name_string',
      'Firmware tree의 이름을 root부터 출력할 때 부모 참조와 현재 노드의 소유권을 구분합니다.',
      'Parent 개수를 얻고 depth를 큰 값부터 0까지 줄입니다. depth>0이면 fwnode_get_nth_parent로 참조를 얻고 0이면 입력 fwnode를 그대로 씁니다. 각 node의 name prefix와 name을 순서대로 출력하고 얻은 parent 참조만 put합니다. fwnode_string은 w selector를 확인하고 P는 이름만, f와 default는 전체 이름을 표시한 뒤 전체 폭을 맞춥니다.',
      'Caller가 현재 node의 수명을 보장하고 helper가 얻은 parent 참조만 정리하는 규칙을 지킵니다. Firmware path와 파일시스템 pathname을 같은 자료로 해석하지 않습니다. Prefix가 제공하는 separator를 임의 slash 규칙으로 바꾸지 않습니다.',
      'depth 감소, parent 획득, prefix/name, depth 조건 put과 outer padding을 읽으세요.',
      [('Depth 0에서 입력 node도 새 참조를 얻고 put하는가?', '입력 node를 그대로 쓰며 이 경로는 put하지 않는다','모든 node의 refcount를 무조건 줄인다','원본은 parent node에만 새 참조를 얻습니다. Caller 소유 입력 node의 참조를 이 helper가 반납하지 않습니다.'),
       ('전체 이름의 출력 순서는?', 'root부터 현재 node 순서이다','현재 node부터 root 순서이다','Parent 개수부터 depth를 줄이며 높은 parent의 prefix와 name을 먼저 표시합니다.')],
      [('Refcount 0 조건','원본 주석은 현재 fwnode의 refcount가 0일 수 있어 다른 node만 참조를 얻는다고 설명합니다. 단순한 균형 맞추기라는 이유로 입력 node에 get/put을 추가하지 않습니다.'),
       ('폭 적용','fwnode_string은 내부 str_spec의 field_width를 -1로 두어 각 부분을 따로 pad하지 않습니다. 전체 작성 길이를 계산한 뒤 outer widen_string을 한 번 적용합니다.')])
    lesson('Device Tree 표시·선택 필드와 Compatible 목록','device_node_string',
      'Device Tree 객체에서 필요한 정보만 골라 출력하는 format 파서와 전체 폭 적용 방식을 배웁니다.',
      'F selector와 CONFIG_OF를 확인하고 pointer 검사 뒤 알려진 suffix가 없으면 f로 기본 선택합니다. f는 전체 이름,n은 @ 앞 이름,p는 phandle,P는 name path,F는 D/d/P/B 상태 문자를 표시합니다. c는 첫 compatible, C는 모든 compatible 문자열을 quote와 comma로 연결합니다. 여러 suffix의 결과 사이에 colon을 넣고 마지막에 전체 widen_string을 적용합니다.',
      '유효 device_node 수명과 OF 설정을 확인합니다. Compatible 표시는 driver match나 device probe 수행과 구분합니다. n은 unit address의 @ 뒤를 제외하는 표시이며 node 객체 이름을 수정하지 않습니다.',
      'fnpPFcC 허용 집합, n의 precision 교체, C 반복, 전체 폭을 읽으세요.',
      [('n이 uart@1000의 표시에서 사용하는 부분은?', 'uart이다','@1000만 표시한다','strchrnul로 @ 위치를 찾아 그 앞 길이를 임시 precision으로 사용합니다. 출력 후 원래 precision을 복구합니다.'),
       ('C와 c의 compatible 표시 차이는?', 'C는 전체 목록,c는 첫 문자열이다','두 선택은 언제나 같은 단일 값이다','C는 property의 모든 문자열을 반복하고 c는 단일 read helper를 사용합니다.')],
      [('Flag 문자','F는 dynamic D,detached d,populated P,populated bus B를 각각 한 칸으로 표시합니다. 없는 상태는 hyphen입니다. Numeric bitmask 출력과 다른 고정 네 문자 표시입니다.'),
       ('Padding과 Precision','부분 str_spec의 폭은 -1이지만 precision은 유지하며 n에서만 임시로 @ 앞 길이를 사용합니다. 전체 폭은 마지막 한 번 적용합니다. Compatible의 quote 추가가 일반 escape engine 사용을 뜻하는 것은 아닙니다.')])
